 void invalidateContactCaches(){synchronized(contactCache){contactCache.clear();contactCacheGeneration++;}synchronized(contactBitmapCache){contactBitmapCache.evictAll();}synchronized(contactPhotoPending){contactPhotoPending.clear();}synchronized(contactLookupPending){contactLookupPending.clear();}contactsLoaded=false;contactsLoadInProgress=false;contactsGeneration++;if(list!=null&&!isFinishing()&&!isDestroyed()){if(isThreadListFilter(filter))loadThreadRows();else render();}}
 @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag") void registerSmsUpdatedReceiver(){if(smsUpdatedReceiverRegistered)return;IntentFilter filter=new IntentFilter(SmsReceiver.ACTION_SMS_UPDATED);if(Build.VERSION.SDK_INT>=33)registerReceiver(smsUpdatedReceiver,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(smsUpdatedReceiver,filter);smsUpdatedReceiverRegistered=true;}
