 void showMoreScreen(){
  threadHandler.removeCallbacks(threadRefreshRunnable);threadHandler.removeCallbacks(searchFilterRunnable);threadsRecycler.setVisibility(View.GONE);emptyThreadsView.setVisibility(View.GONE);otherScroll.setVisibility(View.VISIBLE);list.removeAllViews();list.addView(tv("المزيد",22));list.addView(tv("أدوات الرسائل وإدارتها",13));
  String[][] sections={{"الرسائل الجماعية","bulk"},{"الرسائل المجدولة","scheduled"},{"المحادثات المؤرشفة","archived"},{"الرسائل المميزة","starred"},{"الأرقام المحظورة","blocked"},{"المهملات","trash"},{"الرسائل التي تعذّر إرسالها","failed"},{"قواعد توجيه الرسائل","rules"}};
  for(String[] section:sections){Button b=button(section[0]);b.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);b.setCompoundDrawablesRelativeWithIntrinsicBounds(R.drawable.ic_arrow_back,0,0,0);b.setCompoundDrawablePadding(UiResources.dp(this,10));b.setOnClickListener(v->{filter=section[1];selectedBottomTab="more";render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,52);lp.bottomMargin=6;list.addView(b,lp);}updateBottomNavigation();
 }
  boolean isThreadListFilter(String value){return "all".equals(value)||"unread".equals(value)||"archived".equals(value)||"blocked".equals(value);}
  void onSmsUpdated(){if(isThreadListFilter(filter)){threadHandler.removeCallbacks(threadRefreshRunnable);threadHandler.postDelayed(threadRefreshRunnable,250);}else render();}
  void onSearchChanged(){if("contacts".equals(filter)){contactsHandler.removeCallbacks(contactsSearchRunnable);contactsHandler.postDelayed(contactsSearchRunnable,200);}else if(isThreadListFilter(filter)){threadHandler.removeCallbacks(searchFilterRunnable);threadHandler.postDelayed(searchFilterRunnable,200);}else render();}
  void render(){if(list==null)return;updateBottomNavigation();boolean special="contacts".equals(filter)||"more".equals(filter);if(filtersScroll!=null)filtersScroll.setVisibility(special?View.GONE:View.VISIBLE);if(composeButton!=null)composeButton.setVisibility(special?View.GONE:View.VISIBLE);if("contacts".equals(filter)){showContactsScreen();return;}if("more".equals(filter)){contactsScreen.setVisibility(View.GONE);showMoreScreen();return;}contactsScreen.setVisibility(View.GONE);if(isThreadListFilter(filter)){otherScroll.setVisibility(View.GONE);threadsRecycler.setVisibility(View.VISIBLE);emptyThreadsView.setVisibility(View.GONE);loadThreadRows();return;}threadHandler.removeCallbacks(threadRefreshRunnable);threadHandler.removeCallbacks(searchFilterRunnable);threadsRecycler.setVisibility(View.GONE);emptyThreadsView.setVisibility(View.GONE);otherScroll.setVisibility(View.VISIBLE);list.removeAllViews();if("trash".equals(filter)){trashScreen();return;}if("starred".equals(filter)){starredScreen();return;}if("bulk".equals(filter)){bulkScreen();return;}if("groups".equals(filter)){groupsScreen();return;}if("rules".equals(filter)){forwardRulesScreen();return;}if("scheduled".equals(filter)){scheduledScreen();return;}if("failed".equals(filter)){failedScreen();return;}}
  void loadThreadRows(){if(!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;final String requestedFilter=filter;final long generation=++threadGeneration;if(pendingThreadsLoad!=null)pendingThreadsLoad.cancel(true);pendingThreadsLoad=DATA_EXECUTOR.submit(()->{ArrayList<ThreadItem> rows=new ArrayList<>();android.database.Cursor c=null;try{c=db.listThreads(requestedFilter);while(c.moveToNext()){if(Thread.currentThread().isInterrupted())return;String address=c.getString(c.getColumnIndexOrThrow("address"));String body=c.getString(c.getColumnIndexOrThrow("body"));String status=c.getString(c.getColumnIndexOrThrow("status"));long stamp=0;try{stamp=Long.parseLong(c.getString(c.getColumnIndexOrThrow("ts")));}catch(Exception ignored){}ContactData contact=loadContactData(address);rows.add(new ThreadItem(address,body==null?"":body,status==null?"":status,stamp,contact.name,contact.photoUri,contact.photo));}}catch(Exception e){android.util.Log.e("HashemSMS","Unable to load conversation list; keeping the previous list",e);return;}finally{if(c!=null)try{c.close();}catch(Exception e){android.util.Log.w("HashemSMS","Unable to close conversation cursor",e);}}if(Thread.currentThread().isInterrupted())return;runOnUiThread(()->{if(generation!=threadGeneration||!isThreadListFilter(filter)||!requestedFilter.equals(filter)||isFinishing()||isDestroyed())return;allThreadItems=rows;applyThreadSearch();});});}
  void applyThreadSearch(){if(!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;final String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);final long generation=++filterGeneration;final ArrayList<ThreadItem> snapshot=new ArrayList<>(allThreadItems);if(pendingFilterTask!=null)pendingFilterTask.cancel(true);pendingFilterTask=DATA_EXECUTOR.submit(()->{ArrayList<ThreadItem> result=new ArrayList<>();for(ThreadItem item:snapshot){if(Thread.currentThread().isInterrupted())return;if(query.isEmpty()||item.address.toLowerCase(Locale.ROOT).contains(query)||item.body.toLowerCase(Locale.ROOT).contains(query)||item.contact.toLowerCase(Locale.ROOT).contains(query))result.add(item);}runOnUiThread(()->{if(generation!=filterGeneration||!isThreadListFilter(filter)||isFinishing()||isDestroyed())return;threadAdapter.submitList(result);emptyThreadsView.setVisibility(result.isEmpty()?View.VISIBLE:View.GONE);});});}
  ContactData loadContactData(String number){synchronized(contactCache){ContactData cached=contactCache.get(number);if(cached!=null)return new ContactData(cached.name,cached.photoUri,contactBitmapCache.get(number));}String name="";Uri photoUri=null;android.database.Cursor cursor=null;try{Uri uri=Uri.withAppendedPath(ContactsContract.PhoneLookup.CONTENT_FILTER_URI,Uri.encode(number));cursor=getContentResolver().query(uri,new String[]{ContactsContract.PhoneLookup.DISPLAY_NAME,ContactsContract.PhoneLookup.PHOTO_THUMBNAIL_URI},null,null,null);if(cursor!=null&&cursor.moveToFirst()){String found=cursor.getString(0);name=found==null?"":found;String raw=cursor.getString(1);if(raw!=null&&!raw.trim().isEmpty())photoUri=Uri.parse(raw);}}catch(Exception e){android.util.Log.w("HashemSMS","Contact lookup failed",e);}finally{if(cursor!=null)try{cursor.close();}catch(Exception e){android.util.Log.w("HashemSMS","Unable to close contact cursor",e);}}ContactData loaded=new ContactData(name,photoUri,null);synchronized(contactCache){ContactData raced=contactCache.get(number);if(raced!=null)loaded=raced;else contactCache.put(number,loaded);}return new ContactData(loaded.name,loaded.photoUri,contactBitmapCache.get(number));}
  void loadContactPhotoAsync(String number,Uri photoUri,ImageView image,TextView fallback){if(photoUri==null)return;android.graphics.Bitmap cached=contactBitmapCache.get(number);if(cached!=null){if(number.equals(image.getTag())){image.setImageBitmap(cached);image.setVisibility(View.VISIBLE);fallback.setVisibility(View.GONE);}return;}final long generation;synchronized(contactCache){generation=contactCacheGeneration;}synchronized(contactPhotoPending){if(!contactPhotoPending.add(number))return;}IMAGE_EXECUTOR.execute(()->{android.graphics.Bitmap bitmap=null;java.io.InputStream in=null;try{in=getContentResolver().openInputStream(photoUri);if(in!=null)bitmap=android.graphics.BitmapFactory.decodeStream(in);}catch(Exception e){android.util.Log.w("HashemSMS","Contact thumbnail decode failed",e);}finally{if(in!=null)try{in.close();}catch(Exception ignored){}}synchronized(contactPhotoPending){contactPhotoPending.remove(number);}if(bitmap==null)return;synchronized(contactCache){ContactData current=contactCache.get(number);if(generation!=contactCacheGeneration||current==null||!java.util.Objects.equals(current.photoUri,photoUri))return;}contactBitmapCache.put(number,bitmap);final android.graphics.Bitmap loaded=bitmap;runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&number.equals(image.getTag())){image.setImageBitmap(loaded);image.setVisibility(View.VISIBLE);fallback.setVisibility(View.GONE);}if(threadsRecycler!=null){for(int i=0;i<threadsRecycler.getChildCount();i++){View child=threadsRecycler.getChildAt(i);androidx.recyclerview.widget.RecyclerView.ViewHolder vh=threadsRecycler.getChildViewHolder(child);if(vh instanceof ThreadViewHolder){ThreadViewHolder th=(ThreadViewHolder)vh;if(number.equals(th.photo.getTag())){th.photo.setImageBitmap(loaded);th.photo.setVisibility(View.VISIBLE);th.fallback.setVisibility(View.GONE);}}}}});});}
  void loadContactPhotoAsync(String number,Uri photoUri,ThreadViewHolder holder){loadContactPhotoAsync(number,photoUri,holder.photo,holder.fallback);}
