 void starredScreen(){list.addView(tv("الرسائل المميزة",22));list.addView(tv("تظهر هنا الرسائل التي وضعت عليها نجمة داخل المحادثات.",14));android.database.Cursor c=db.list("starred");int n=0;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);while(c.moveToNext()){String a=c.getString(c.getColumnIndexOrThrow("address")),body=c.getString(c.getColumnIndexOrThrow("body")),status=c.getString(c.getColumnIndexOrThrow("status"));if(!q.isEmpty()&&!a.toLowerCase(Locale.ROOT).contains(q)&&!body.toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);TextView starredTitle=tv(contactName(a)+"  ·  "+a,16);starredTitle.setCompoundDrawablesRelativeWithIntrinsicBounds(R.drawable.ic_star,0,0,0);starredTitle.setCompoundDrawablePadding(UiResources.dp(MainActivity.this,6));row.addView(starredTitle);row.addView(tv(body,16));row.addView(tv(status,12));row.setOnClickListener(v->{Intent i=new Intent(this,ConversationActivity.class);i.putExtra("address",a);startActivity(i);});list.addView(row);View line=new View(this);line.setBackgroundColor(UiResources.color(MainActivity.this,R.color.divider));list.addView(line,new LinearLayout.LayoutParams(-1,1));n++;}c.close();if(n==0)list.addView(tv("لا توجد رسائل مميزة حاليًا",17));}
